require "rails_helper"

RSpec.describe Timekeeping::Handoff::LegacySource, :two_tenant_seed, :seeded_without_transaction do
  it "exports the seeded legacy entries as stored without writing audits or billing tables" do
    connection = ActiveRecord::Base.connection
    tables = %w[audits invoices invoice_line_items invoice_line_item_time_entries invoice_taxes timesheet_entries]
    snapshot = -> { tables.to_h { |table| [table, connection.select_rows("SELECT * FROM #{table} ORDER BY id")] } }
    before = snapshot.call
    recorded = YAML.load_file(Timekeeping::SeedDispositionRecorder::DEFAULT_PATH)

    result = described_class.new(connection:, recorded_disposition: recorded)
      .export(generation: 7, captured_at: Time.utc(2026, 10, 25, 12))

    # "Never write the legacy `audits` table." and "The source only reads billing tables; it writes none."
    expect(snapshot.call).to eq(before)

    rows = result[:checkpoint].rows
    # "Entry rows are copied as stored: `duration` as the same float, and `version` as stored (0 from the
    # column default). Nothing infers `billed` from invoice links."
    stored = TimesheetEntry.unscoped.pluck(:id, :company_id, :version, :duration, :bill_status)
      .to_h { |id, company_id, version, duration, bill_status| [id, [company_id, version, duration, bill_status]] }
    copied = rows.fetch("entries").to_h do |row|
      [row["id"], [row["company_id"], row["version"], row["duration"], row["bill_status"]]]
    end
    expect(copied).to eq(stored)
    expect(rows.fetch("entries").map { |row| row["company_id"] }).to all(be_a(Integer))
    expect(rows.fetch("invoice_operations")).to eq([])
    expect(rows.fetch("idempotency_records")).to eq([])

    reserved_ids = recorded.fetch("companies").values.flat_map { |invoices| invoices.values.flat_map { |i| i["entry_ids"] } }
    committed = rows.fetch("reservations").select { |r| r["state"] == "committed" }.map { |r| r["entry_id"] }
    expect(committed).to include(*reserved_ids)
    expect(result[:corrections].map { |c| c["entry_id"] }.sort).to eq(reserved_ids.sort)
  end
end

require "rails_helper"

RSpec.describe Timekeeping::Handoff::LegacySource, :two_tenant_seed, :seeded_without_transaction do
  # "each unlocked link follows its recorded disposition (`reserve` becomes a committed
  # reservation by that invoice). Each corrected entry gets one correction snapshot at
  # version 1 and the new generation."
  it "reserves every recorded seed unlocked link by its invoice with exactly one correction at version 1 and the passed generation" do
    recorded = YAML.load_file(Timekeeping::SeedDispositionRecorder::DEFAULT_PATH)
    captured_at = Time.utc(2026, 10, 24, 12, 0, 0)

    result = described_class.new(connection: ActiveRecord::Base.connection, recorded_disposition: recorded)
      .export(generation: 7, captured_at:)

    reservations = result.fetch(:checkpoint).rows.fetch("reservations")
    corrections = result.fetch(:corrections)
    expected_entry_ids = []

    recorded.fetch("companies").each do |company_name, invoices|
      company = Company.find_by!(name: company_name)
      invoices.each do |invoice_number, listing|
        invoice = Invoice.find_by!(company_id: company.id, invoice_number:)
        listing.fetch("entry_ids").each do |entry_id|
          expected_entry_ids << entry_id
          owned = reservations.select { |row| row["entry_id"] == entry_id }
          expect(owned.size).to eq(1)
          expect(owned.first).to include(
            "company_id" => company.id, "invoice_id" => invoice.id, "state" => "committed"
          )

          entry_corrections = corrections.select { |item| item["entry_id"] == entry_id }
          expect(entry_corrections.size).to eq(1)
          correction = entry_corrections.first
          expect(correction["company_id"]).to eq(company.id)
          expect(correction["generation"]).to eq(7)
          expect(correction["snapshot"]["version"]).to eq(1)
          expect(correction["snapshot"]["locked"]).to be(true)
        end
      end
    end

    expect(expected_entry_ids).not_to be_empty
    # The seed has no re-locks, orphans or conflicts, so only reserved unlocked links are corrected.
    expect(corrections.map { |item| item["entry_id"] }).to match_array(expected_entry_ids)
  end
end

require "rails_helper"

RSpec.describe Timekeeping::Handoff::LegacySource, :two_tenant_seed, :seeded_without_transaction do
  # "Refuse, never guess, when a number is missing, matches no invoice of that company,
  # or would link an entry to another company's invoice."
  # "Cutover proceeds only when the orphan, conflict and unlocked-link lists are empty,
  # or every item has a recorded disposition."
  it "refuses both seeded companies in one error when an invoice number is filed under the other company and a link has no disposition" do
    recorded = YAML.load_file(Timekeeping::SeedDispositionRecorder::DEFAULT_PATH)
    companies = recorded.fetch("companies")
    fork_and_leaf_listing = companies.fetch("Fork & Leaf Salads").delete("FL-0001")
    # FL-0001 exists only in Fork & Leaf Salads; filed under Copper Kettle Bakery it must not resolve.
    companies.fetch("Copper Kettle Bakery")["FL-0001"] = fork_and_leaf_listing
    # Copper Kettle Bakery's own unlocked links lose their disposition.
    companies.fetch("Copper Kettle Bakery").delete("CK-0001")

    source = described_class.new(connection: ActiveRecord::Base.connection, recorded_disposition: recorded)

    expect { source.export(generation: 7, captured_at: Time.utc(2026, 10, 24, 12)) }
      .to raise_error(Timekeeping::Handoff::LegacySource::Refused) { |error|
        expect(error).to be_a(Timekeeping::Handoff::Store::Error)
        refusals = error.refusals
        expect(refusals.keys).to include(fork_and_leaf.id, copper_kettle.id)
        expect(refusals.fetch(fork_and_leaf.id)).not_to be_empty
        expect(refusals.fetch(copper_kettle.id)).not_to be_empty
        expect(refusals.fetch(copper_kettle.id).join("\n")).to include("FL-0001")
        expect(refusals.fetch(copper_kettle.id).join("\n")).to include("CK-0001")
      }
  end
end

