RSpec.describe Timekeeping::Handoff::LegacySource, :two_tenant_seed, :seeded_without_transaction do
  # "Keep its company, author, action, original `created_at` and change values (before and
  # after from `audited_changes`), and set `entry_created_at` from the entry."
  # "Never write the legacy `audits` table."
  it "exports a seeded entry's legacy update audit with its company, author, timestamps and change values and leaves audits unchanged" do
    entry = TimesheetEntry.joins(project: :client).where(clients: { company_id: copper_kettle.id }).order(:id).first
    author = copper_kettle.users.order(:id).first
    audited_at = Time.utc(2026, 1, 15, 9, 30, 0)
    audit = Audited::Audit.create!(
      auditable_type: "TimesheetEntry", auditable_id: entry.id,
      associated_type: "Company", associated_id: copper_kettle.id,
      user_type: "User", user_id: author.id,
      action: "update", audited_changes: { "note" => ["before note", "after note"] },
      created_at: audited_at
    )
    connection = ActiveRecord::Base.connection
    audits_before = connection.select_all("SELECT * FROM audits ORDER BY id").to_a

    result = described_class.new(
      connection:, recorded_disposition: YAML.load_file(Timekeeping::SeedDispositionRecorder::DEFAULT_PATH)
    ).export(generation: 7, captured_at: Time.utc(2026, 10, 24, 12))

    row = result.fetch(:checkpoint).rows.fetch("entry_audits").find { |item| item["id"] == audit.id }
    expect(row).to include(
      "company_id" => copper_kettle.id, "entry_id" => entry.id,
      "actor_type" => "user", "actor_id" => author.id, "action" => "update",
      "before" => { "note" => "before note" }, "after" => { "note" => "after note" }
    )
    expect(row["created_at"]).to eq(audited_at)
    expect(row["entry_created_at"]).to eq(entry.created_at)
    expect(connection.select_all("SELECT * FROM audits ORDER BY id").to_a).to eq(audits_before)
  end
end
